// Helper: mc = multiple_choice, tf = true_false, co = code_output, fc = fill_code
const mc = (d, s, opts, ans, exp, tags=[]) => ({ type:'multiple_choice', difficulty:d, statement:s, options:opts, answer:ans, explanation:exp, tags });
const tf = (d, s, ans, exp, tags=[]) => ({ type:'true_false', difficulty:d, statement:s, options:null, answer:String(ans), explanation:exp, tags });
const co = (d, s, code, ans, exp, tags=[]) => ({ type:'code_output', difficulty:d, statement:s, code_snippet:code, options:null, answer:ans, explanation:exp, tags });
const fc = (d, s, code, ans, exp, tags=[]) => ({ type:'fill_code', difficulty:d, statement:s, code_snippet:code, options:null, answer:ans, explanation:exp, tags });

