async function seed() {
  const { data: subjects } = await sb.from('subjects').select('id, slug');
  const subMap = Object.fromEntries(subjects.map(s => [s.slug, s.id]));

  const allQ = [
    ...PROG.map(q => ({ ...q, subject_id: subMap['programacion'] })),
    ...MARCAS.map(q => ({ ...q, subject_id: subMap['marcas'] })),
    ...BD.map(q => ({ ...q, subject_id: subMap['basesdedatos'] })),
  ];

  // Format for DB
  const rows = allQ.map(q => ({
    subject_id: q.subject_id,
    type: q.type,
    difficulty: q.difficulty,
    statement: q.statement,
    code_snippet: q.code_snippet || null,
    image_url: null,
    options: q.options ? JSON.stringify(q.options) : null,
    answer: JSON.stringify(q.answer),
    explanation: q.explanation,
    tags: q.tags || [],
  }));

  console.log(`Inserting ${rows.length} questions...`);
  console.log(`  Programacion: ${PROG.length}`);
  console.log(`  Marcas: ${MARCAS.length}`);
  console.log(`  Bases de Datos: ${BD.length}`);

  // Insert in batches of 50
  for (let i = 0; i < rows.length; i += 50) {
    const batch = rows.slice(i, i + 50);
    const { error } = await sb.from('questions').insert(batch);
    if (error) {
      console.error(`Batch ${i}-${i+batch.length} error:`, error.message);
    } else {
      console.log(`  Batch ${i+1}-${i+batch.length} OK`);
    }
  }

  console.log('Done!');
}

seed().catch(console.error);
